def initialiser_date_fin(apps, schema_editor):
    """Fige, pour chaque école ayant déjà des paiements, la fin d'abonnement calculée par
    l'ancien mode mensuel (dernier mois payé + périodicité du plan, au jour d'échéance) — aucune
    école ne gagne ni ne perd de jours au passage au décompte en jours. Les écoles sans paiement
    restent sans date (repli sur l'ancienne échéance du mois en cours)."""
    Ecole = apps.get_model("tenants", "Ecole")
    duree = {"trimestriel": 3, "annuel": 12}
    for ecole in Ecole.objects.select_related("plan"):
        dernier = ecole.paiements.order_by("-mois").first()
