        index = dernier.mois.month - 1 + nb_mois
        mois_echeance = date(dernier.mois.year + index // 12, index % 12 + 1, 1)
        ecole.date_fin_abonnement = mois_echeance.replace(day=min(ecole.jour_echeance, 28))
        ecole.save(update_fields=["date_fin_abonnement"])


